// src/lib/plattform/finanzen/pacht.js
//
// Pachtabrechnung (Gutschrift an den Eigentümer) je Fälligkeit – reine Funktionen.
//
// Vertrag (Auszug, camelCase wie im Backend):
//   modell           fest | indexiert | umsatz
//   pachtJahr        Jahrespacht in € (fest/indexiert; bei Umsatzbeteiligung ohne Bedeutung)
//   index            { reihe, basisJahr, basisIndex?, schwellePct, anteilPct, nurErhoehung }   (nur indexiert)
//   umsatz           { anteil (0,04 = 4 %), erloesCtKwh, mindestJahr }                          (nur umsatz)
//   reservierungJahr Reservierungsprämie in €/Jahr bis zum Pachtbeginn
//   flaecheHa        nur für Texte (€/ha)
//
// Ergebnis { positionen[{art, artikel, text, menge, einheit, preis, betrag}], netto, erklaerung[], klaerung|null, basis{…} }

import { indexErklaerung, indexiertePacht } from "./indexierung.js";
import { INDEX_REIHEN } from "./konstanten.js";
import { datumDe, jahrVon, rund, rund2, summe, zahlDe } from "./basis.js";

const zeitraumText = (f) => `${datumDe(f.von)} – ${datumDe(f.bis)}${f.anteil < 0.9999 ? ` (anteilig ${f.tage}/${f.tageVoll} Tage)` : ""}`;

/** Umsatzbeteiligung einer Periode: max(Anteil × Erlös, Mindestpacht anteilig) */
export function umsatzbeteiligung({ ertragKwh, erloesCtKwh, anteil, mindestJahr = 0, faktorJahr = 1 }) {
  const erloesEur = rund2((Number(ertragKwh) || 0) * (Number(erloesCtKwh) || 0) / 100);
  const anteilEur = rund2(erloesEur * (Number(anteil) || 0));
  const mindestEur = rund2((Number(mindestJahr) || 0) * faktorJahr);
  const betrag = Math.max(anteilEur, mindestEur);
  return { erloesEur, anteilEur, mindestEur, betrag: rund2(betrag), mindestGreift: mindestEur > anteilEur };
}

/**
 * Positionen einer fälligen Periode.
 * f:  Fälligkeit aus faelligkeiten() { phase, von, bis, anteil, faktorJahr, … }
 * kontext: { indexTabelle: [{reihe, jahr, wert}], ertragKwh (nur umsatz: Erzeugung der Periode lt. Monatswerten), ertragFehlt: [monate] }
 */
export function pachtPositionen(vertrag, f, { indexTabelle = [], ertragKwh = null, ertragFehlt = [] } = {}) {
  const positionen = [];
  const erklaerung = [];
  let klaerung = null;
  const ha = Number(vertrag.flaecheHa) || 0;
  const jahr = jahrVon(f.von);

  if (f.phase === "reservierung") {
    const betrag = rund2(Number(vertrag.reservierungJahr) * f.faktorJahr);
    positionen.push({ art: "reservierung", artikel: "PACHT-RES", text: `Reservierungsprämie ${zeitraumText(f)}`, menge: rund(f.faktorJahr, 4), einheit: "Jahr", preis: rund2(vertrag.reservierungJahr), betrag });
    erklaerung.push(`Bis zum Pachtbeginn erhalten Sie eine Reservierungsprämie von ${zahlDe(vertrag.reservierungJahr, 2)} € pro Jahr${ha ? ` (${zahlDe(vertrag.reservierungJahr / ha, 2)} €/ha)` : ""}, abgerechnet nach Ablauf jedes Zeitraums.`);
    return { positionen, netto: summe(positionen, "betrag"), erklaerung, klaerung, basis: { jahresbetrag: rund2(vertrag.reservierungJahr) } };
  }

  if (vertrag.modell === "umsatz") {
    const u = vertrag.umsatz || {};
    if (ertragKwh === null || ertragFehlt.length) {
      klaerung = `Ertragsdaten der Anlage fehlen für ${ertragFehlt.length ? ertragFehlt.join(", ") : "den Zeitraum"} – Umsatzbeteiligung kann nicht berechnet werden.`;
      return { positionen, netto: 0, erklaerung, klaerung, basis: {} };
    }
    const r = umsatzbeteiligung({ ertragKwh, erloesCtKwh: u.erloesCtKwh, anteil: u.anteil, mindestJahr: u.mindestJahr, faktorJahr: f.faktorJahr });
    positionen.push({
      art: "umsatz", artikel: "PACHT-UMSATZ",
      text: `Umsatzbeteiligung ${rund(u.anteil * 100, 2)} % ${zeitraumText(f)} – Erlös ${zahlDe(r.erloesEur, 2)} € (${zahlDe(ertragKwh)} kWh × ${zahlDe(u.erloesCtKwh, 3)} ct/kWh)`,
      menge: 1, einheit: "Pauschale", preis: r.anteilEur, betrag: r.anteilEur,
    });
    if (r.mindestGreift) positionen.push({ art: "mindest", artikel: "PACHT-UMSATZ", text: `Aufstockung auf die Mindestpacht (${zahlDe(u.mindestJahr, 2)} €/Jahr, anteilig ${zahlDe(r.mindestEur, 2)} €)`, menge: 1, einheit: "Pauschale", preis: rund2(r.mindestEur - r.anteilEur), betrag: rund2(r.mindestEur - r.anteilEur) });
    erklaerung.push(`Sie erhalten ${rund(u.anteil * 100, 2)} % der Stromerlöse der Anlage, mindestens ${zahlDe(u.mindestJahr, 2)} € pro Jahr. Grundlage sind die geeichten Zählerstände (Erzeugung) und ein vereinbarter Erlös von ${zahlDe(u.erloesCtKwh, 3)} ct/kWh.`);
    if (r.mindestGreift) erklaerung.push("In diesem Zeitraum lag der Erlösanteil unter der Mindestpacht – ausgezahlt wird die Mindestpacht.");
    return { positionen, netto: summe(positionen, "betrag"), erklaerung, klaerung, basis: { ...r, ertragKwh } };
  }

  // fest bzw. indexiert: Jahrespacht × Anteil der Periode
  let jahresbetrag = rund2(vertrag.pachtJahr);
  if (vertrag.modell === "indexiert") {
    const regel = { ...vertrag.index, basisBetrag: vertrag.pachtJahr, tabelle: indexTabelle };
    const verlauf = indexiertePacht(regel, jahr);
    if (verlauf.fehlt?.length) klaerung = `Indexwert fehlt (${INDEX_REIHEN[regel.reihe]?.label || regel.reihe}, ${verlauf.fehlt.join(", ")}) – bitte unter „Index (VPI)“ nachtragen.`;
    jahresbetrag = verlauf.betrag;
    erklaerung.push(...indexErklaerung(regel, verlauf, INDEX_REIHEN[regel.reihe]?.label));
    erklaerung.push(`Jahrespacht ${jahr}: ${zahlDe(jahresbetrag, 2)} € (Ausgangswert ${zahlDe(vertrag.pachtJahr, 2)} €).`);
  } else {
    erklaerung.push(`Feste Jahrespacht ${zahlDe(jahresbetrag, 2)} €${ha ? ` (${zahlDe(jahresbetrag / ha, 2)} €/ha bei ${zahlDe(ha, 2)} ha)` : ""}.`);
  }
  const betrag = rund2(jahresbetrag * f.faktorJahr);
  positionen.push({ art: vertrag.modell === "indexiert" ? "index" : "pacht", artikel: "PACHT", text: `${vertrag.modell === "indexiert" ? "Pacht (wertgesichert)" : "Pacht"} ${zeitraumText(f)}`, menge: rund(f.faktorJahr, 4), einheit: "Jahr", preis: jahresbetrag, betrag });
  return { positionen, netto: summe(positionen, "betrag"), erklaerung, klaerung, basis: { jahresbetrag } };
}

/** Monate („JJJJ-MM“) eines Zeitraums – für die Ertragssumme der Umsatzbeteiligung */
export function monateImZeitraum(von, bis) {
  const liste = [];
  let [j, m] = [jahrVon(von), Number(String(von).slice(5, 7))];
  const [jb, mb] = [jahrVon(bis), Number(String(bis).slice(5, 7))];
  while (j < jb || (j === jb && m <= mb)) {
    liste.push(`${j}-${String(m).padStart(2, "0")}`);
    m += 1;
    if (m > 12) {
      m = 1;
      j += 1;
    }
  }
  return liste;
}

/**
 * Erzeugung (kWh) einer Periode aus Zählerstand-Monatswerten (nur Register 2.8.0 der Erzeugungszähler).
 * Teilmonate am Rand werden taggenau anteilig gerechnet. Rückgabe { kwh, fehlt: [monat…] }
 */
export function ertragAusMonatswerten(zeilen, messpunkte, von, bis) {
  const erz = new Set((messpunkte || []).filter((m) => m.art === "erzeugung" && m.abrechnungsrelevant).map((m) => m.id));
  const fehlt = [];
  let kwh = 0;
  if (!erz.size) return { kwh: null, fehlt: ["kein abrechnungsrelevanter Erzeugungszähler"] };
  for (const monat of monateImZeitraum(von, bis)) {
    const werte = (zeilen || []).filter((z) => z.monat === monat && erz.has(z.messpunktId) && z.register === "2.8.0");
    if (werte.length < erz.size || werte.some((w) => w.menge === null || w.menge === undefined)) {
      fehlt.push(monat);
      continue;
    }
    const [j, mm] = monat.split("-").map(Number);
    const tageMonat = new Date(Date.UTC(j, mm, 0)).getUTCDate();
    const start = monat === String(von).slice(0, 7) ? Number(String(von).slice(8)) : 1;
    const ende = monat === String(bis).slice(0, 7) ? Number(String(bis).slice(8)) : tageMonat;
    kwh += werte.reduce((s, w) => s + Number(w.menge), 0) * ((ende - start + 1) / tageMonat);
  }
  return { kwh: fehlt.length ? null : Math.round(kwh), fehlt };
}
// src/lib/plattform/finanzen/indexierung.js
//
// Wertsicherung (Indexierung) einer Jahrespacht über einen Verbraucherpreisindex – reine Funktionen.
//
// Regel (je Vertrag einstellbar):
//   basisBetrag   Jahrespacht bei Vertragsschluss (€)
//   basisJahr     Jahr des Basisindex (Jahresdurchschnitt), basisIndex optional (sonst aus der Tabelle)
//   reihe         Index-Reihe (VPI-AT-2020, VPI-DE-2020, LIK-CH-2020)
//   schwellePct   Anpassung erst, wenn die Änderung seit der letzten Anpassung die Schwelle erreicht (0 = jährlich)
//   anteilPct     Weitergabe der Änderung in % (100 = voll)
//   nurErhoehung  nur Erhöhungen weitergeben (Hinweis: in DE nach § 2 Abs. 3 PrKG problematisch – Klauseln müssen
//                 in der Regel in beide Richtungen wirken; mit Rechtsberatung prüfen)
//
// Anpassung zum 1.1. jedes Jahres J ab dem ersten Abrechnungsjahr nach dem Basisjahr: Vergleich Jahresdurchschnitt
// J−1 mit dem Index der letzten Anpassung. Neue Pacht = alte Pacht × (1 + Anteil × (I(J−1) / I(letzte) − 1)).
// Fehlt ein Indexwert, bleibt der letzte Betrag stehen und das Ergebnis meldet `fehlt` (→ Klärfall).

import { euro, rund, rund2, zahlDe } from "./basis.js";

/** Indexwert aus der Tabelle [{reihe, jahr, wert}] */
export function indexWert(tabelle, reihe, jahr) {
  const t = (tabelle || []).find((x) => x.reihe === reihe && Number(x.jahr) === Number(jahr));
  return t && Number.isFinite(Number(t.wert)) && Number(t.wert) > 0 ? Number(t.wert) : null;
}

/**
 * Verlauf der Wertsicherung bis einschließlich `bisJahr`.
 * Rückgabe { schritte: [{jahr, referenzJahr, index, basisIndex, aenderungPct, angepasst, betrag, text}], betrag, fehlt: [jahr…] }
 */
export function indexVerlauf({ basisBetrag, basisJahr, basisIndex, reihe, tabelle, bisJahr, schwellePct = 0, anteilPct = 100, nurErhoehung = false }) {
  const start = Number(basisIndex) > 0 ? Number(basisIndex) : indexWert(tabelle, reihe, basisJahr);
  let betrag = rund2(basisBetrag);
  const schritte = [];
  const fehlt = [];
  if (!start) {
    return { schritte, betrag, fehlt: [Number(basisJahr)], basisIndex: null };
  }
  let letzterIndex = start;
  const anteil = Math.max(0, Math.min(100, Number(anteilPct ?? 100))) / 100;
  const schwelle = Math.max(0, Number(schwellePct) || 0) / 100;
  for (let jahr = Number(basisJahr) + 1; jahr <= Number(bisJahr); jahr++) {
    const ref = jahr - 1;
    const idx = ref === Number(basisJahr) ? start : indexWert(tabelle, reihe, ref);
    if (!idx) {
      fehlt.push(ref);
      schritte.push({ jahr, referenzJahr: ref, index: null, basisIndex: letzterIndex, aenderungPct: null, angepasst: false, betrag, text: `Indexwert ${ref} fehlt – Betrag unverändert` });
      continue;
    }
    const aenderung = idx / letzterIndex - 1;
    let angepasst = false;
    let text;
    if (Math.abs(aenderung) < 1e-12) text = "keine Indexänderung";
    else if (nurErhoehung && aenderung < 0) text = "Index gesunken – vereinbart ist nur eine Erhöhung";
    else if (Math.abs(aenderung) + 1e-12 < schwelle) text = `Änderung ${zahlDe(aenderung * 100, 2)} % unter der Schwelle von ${zahlDe(schwelle * 100, 2)} %`;
    else {
      const alt = betrag;
      betrag = rund2(betrag * (1 + anteil * aenderung));
      angepasst = true;
      text = `Anpassung ${aenderung > 0 ? "+" : ""}${zahlDe(aenderung * anteil * 100, 2)} % (Index ${zahlDe(letzterIndex, 1)} → ${zahlDe(idx, 1)}${anteil < 1 ? `, ${zahlDe(anteil * 100, 0)} % weitergegeben` : ""}): ${euro(alt)} → ${euro(betrag)}`;
    }
    schritte.push({ jahr, referenzJahr: ref, index: idx, basisIndex: letzterIndex, aenderungPct: rund(aenderung * 100, 3), angepasst, betrag, text });
    if (angepasst) letzterIndex = idx;
  }
  return { schritte, betrag, fehlt, basisIndex: start };
}

/** Jahrespacht für ein Kalenderjahr (Wertsicherung bis zu diesem Jahr) */
export function indexiertePacht(regel, jahr) {
  if (Number(jahr) <= Number(regel.basisJahr)) return { betrag: rund2(regel.basisBetrag), schritte: [], fehlt: [], basisIndex: regel.basisIndex || null };
  return indexVerlauf({ ...regel, bisJahr: jahr });
}

/** Verständliche Erklärung für Eigentümer (Portal, Beleg) */
export function indexErklaerung(regel, verlauf, reiheLabel = regel.reihe) {
  const zeilen = [
    `Ihre Pacht ist wertgesichert über den ${reiheLabel} (Basisjahr ${regel.basisJahr}${verlauf.basisIndex ? `, Indexwert ${zahlDe(verlauf.basisIndex, 1)}` : ""}).`,
    Number(regel.schwellePct) > 0
      ? `Angepasst wird, sobald sich der Index seit der letzten Anpassung um mindestens ${zahlDe(regel.schwellePct, Number(regel.schwellePct) % 1 ? 1 : 0)} % verändert hat.`
      : "Angepasst wird jährlich zum 1. Januar anhand des Jahresdurchschnitts des Vorjahres.",
  ];
  if (Number(regel.anteilPct ?? 100) < 100) zeilen.push(`Weitergegeben werden ${zahlDe(regel.anteilPct, 0)} % der Indexänderung.`);
  for (const s of verlauf.schritte.filter((x) => x.angepasst || x.index === null)) zeilen.push(`${s.jahr}: ${s.text}`);
  return zeilen;
}
// src/lib/plattform/finanzen/faelligkeit.js
//
// Abrechnungsperioden und Fälligkeiten eines Pachtvertrags – reine Funktionen.
//
// Perioden sind kalendergebunden (Jahr, Halbjahr, Quartal, Monat). Beginnt oder endet der Vertrag innerhalb einer
// Periode, wird taggenau anteilig gerechnet (`anteil` = Vertragstage / Periodentage).
//
// Phasen:
//   reservierung  vom Vertragsdatum bis zum Tag vor dem Pachtbeginn (Baubeginn/Inbetriebnahme). Ist der Beginn noch
//                 offen, laufen die Perioden bis zum Stichtag. Die Reservierungsprämie wird IMMER nachschüssig
//                 abgerechnet – so entsteht beim späteren Pachtbeginn keine Rückforderung.
//   pacht         vom Pachtbeginn bis zum Laufzeitende (Beginn + Laufzeit − 1 Tag), Zahlweise laut Vertrag.
//
// Fällig: vorschüssig am ersten Tag der Periode + Zahlungsziel, nachschüssig am Tag nach Periodenende + Zahlungsziel.
// Abgerechnet (Gutschrift erzeugt) wird eine Periode, sobald der Erstellungstag erreicht ist:
//   vorschüssig   `vorlaufTage` vor der Fälligkeit (Eigentümer erhält die Gutschrift rechtzeitig)
//   nachschüssig  nach Ablauf der Periode

import { RHYTHMEN } from "./konstanten.js";
import { istDatum, jahrVon, monatVon, monatsAnfang, monatsEnde, plusTage, tageZwischen } from "./basis.js";

/** Kalenderperiode, die den Tag `datum` enthält */
export function periodeVon(datum, rhythmus) {
  const monate = RHYTHMEN[rhythmus]?.monate || 12;
  const j = jahrVon(datum);
  const startMonat = Math.floor((monatVon(datum) - 1) / monate) * monate + 1;
  return { von: monatsAnfang(j, startMonat), bis: monatsEnde(j, startMonat + monate - 1) };
}

/** Perioden zwischen ab und bis (beide inklusive, bis optional = offen, dann bis `stopp`) */
export function perioden({ ab, bis = null, rhythmus = "jaehrlich", stopp }) {
  if (!istDatum(ab)) return [];
  const ende = bis && istDatum(bis) ? bis : stopp;
  if (!ende || ende < ab) return [];
  const liste = [];
  let p = periodeVon(ab, rhythmus);
  for (let i = 0; i < 1200 && p.von <= ende; i++) {
    const von = ab > p.von ? ab : p.von;
    const bisTag = bis && bis < p.bis ? bis : p.bis;
    const tageVoll = tageZwischen(p.von, p.bis) + 1;
    const tage = tageZwischen(von, bisTag) + 1;
    liste.push({ periodeVon: p.von, periodeBis: p.bis, von, bis: bisTag, tage, tageVoll, anteil: tage / tageVoll, monate: RHYTHMEN[rhythmus]?.monate || 12 });
    p = periodeVon(plusTage(p.bis, 1), rhythmus);
  }
  return liste;
}

/** Laufzeitende = Beginn + Laufzeit (Jahre) − 1 Tag */
export function laufzeitEnde(beginn, laufzeitJahre) {
  if (!istDatum(beginn) || !(Number(laufzeitJahre) > 0)) return null;
  const j = jahrVon(beginn) + Number(laufzeitJahre);
  const md = String(beginn).slice(4);
  const ziel = md === "-02-29" ? `${j}-02-28` : `${j}${md}`;
  return plusTage(ziel, istDatum(ziel) ? -1 : 0);
}

/**
 * Alle Fälligkeiten eines Vertrags bis `stichtag` (inkl. künftiger Perioden bis `ausblickBis` für „nächste Zahlung“).
 * vertrag: { id, vertragsdatum, beginn, laufzeitJahre, faelligkeit, zahlweise, zahlungszielTage, reservierungJahr, vorlaufTage }
 * Rückgabe: [{ schluessel, phase, von, bis, anteil, faktorJahr, faelligAm, erstellbarAb, zahlweise }]
 */
export function faelligkeiten(vertrag, { stichtag, ausblickBis = null } = {}) {
  const rhythmus = RHYTHMEN[vertrag.faelligkeit] ? vertrag.faelligkeit : "jaehrlich";
  const ziel = Math.max(0, Number(vertrag.zahlungszielTage ?? 14));
  const vorlauf = Math.max(0, Number(vertrag.vorlaufTage ?? 14));
  const stopp = ausblickBis && ausblickBis > stichtag ? ausblickBis : stichtag;
  const ergebnis = [];
  const eintrag = (phase, p, zahlweise) => {
    const faelligAm = zahlweise === "vorschuessig" ? plusTage(p.von, ziel) : plusTage(p.bis, 1 + ziel);
    const erstellbarAb = zahlweise === "vorschuessig" ? plusTage(faelligAm, -vorlauf - ziel) : plusTage(p.bis, 1);
    ergebnis.push({
      schluessel: `${vertrag.id}:${phase}:${p.von}`,
      phase, von: p.von, bis: p.bis, anteil: p.anteil, tage: p.tage, tageVoll: p.tageVoll,
      // Anteil eines Jahresbetrags: Periodenlänge in Monaten / 12 × taggenauer Anteil
      faktorJahr: (p.monate / 12) * p.anteil,
      faelligAm, erstellbarAb, zahlweise,
    });
  };
  // Reservierungsprämie bis zum Pachtbeginn (nachschüssig)
  if (Number(vertrag.reservierungJahr) > 0 && istDatum(vertrag.vertragsdatum)) {
    const resBis = istDatum(vertrag.beginn) ? plusTage(vertrag.beginn, -1) : null;
    if (!resBis || resBis >= vertrag.vertragsdatum) {
      // offener Beginn: Perioden werden fortgeschrieben; abgerechnet wird erst nach Periodenende (nachschüssig)
      for (const p of perioden({ ab: vertrag.vertragsdatum, bis: resBis, rhythmus, stopp })) eintrag("reservierung", p, "nachschuessig");
    }
  }
  if (istDatum(vertrag.beginn)) {
    const ende = laufzeitEnde(vertrag.beginn, vertrag.laufzeitJahre);
    for (const p of perioden({ ab: vertrag.beginn, bis: ende, rhythmus, stopp })) eintrag("pacht", p, vertrag.zahlweise === "vorschuessig" ? "vorschuessig" : "nachschuessig");
  }
  return ergebnis;
}

/** Fällige (abzurechnende) Perioden zum Stichtag */
export const abzurechnen = (vertrag, stichtag) => faelligkeiten(vertrag, { stichtag }).filter((f) => f.erstellbarAb <= stichtag);

/** Nächste künftige Zahlung ab Stichtag (für „nächste Zahlung“ im Portal) */
export function naechsteFaelligkeit(vertrag, stichtag) {
  const bis = plusTage(stichtag, 800);
  return faelligkeiten(vertrag, { stichtag, ausblickBis: bis }).find((f) => f.faelligAm >= stichtag) || null;
}

