 *   KSV1870-Rating:            ≤ 299 grün, ≤ 399 gelb, sonst rot
 *   D&B Failure Score (1–100): ≥ 51 grün, ≥ 21 gelb, sonst rot
 */
export function bonitaetAmpel(anbieter, score) {
  const s = Number(score);
  if (!Number.isFinite(s)) return "unbekannt";
